effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        float hash(float f){return fract(sin(f*32.34182) * 43758.5453);}
        float hash(vec2 p){return fract(sin(dot(p.xy ,vec2(12.9898,78.233))) * 43758.5453);}

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scalex? (scale+3.0) : scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((30.0+position.x), (-105.0+position.y))*vec2(-1.,1.)/500.;

        vec2 xnxx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        xnxx.y *=acLayerSize.y/acLayerSize.x;


        /////////////////////////

        // if(progressa <= 0.0) { gl_FragColor = texture2DCv(inputImg.texture,acScreenNorm); }
        // else if(progressa >= 0.0001) { 

    	vec4 fragColor;

              	float 
                t = progressa,
                sgn,h,h2,h3,band,ff,df=0.;

            vec2 
                s = vec2(acScreenSize.x,acScreenSize.y),
                uv= TanRyu;
                // uv= (2.*fragCoord-s)/s.y;

                vec3 dir;
                if(typeX==0) { dir =-normalize(vec3(-10.,2.*t/1000.,-4.*t/1000.)); }
                else if(typeX==1) { invertxy? dir =-normalize(vec3(-10.,2.*sin(t/(101.0-progressc)),5.0*sin(t/(101.0-progressb)))) : dir =-normalize(vec3(-10., 2.*sin(t/(101.0-progressb)),5.0*sin(t/(101.0-progressc)))); }
                else if(typeX==2) { invertxy? dir =-normalize(vec3(-10.,2.*sin(t/(101.0-progressc)),5.0*tan(t/(101.0-progressb)))) : dir =-normalize(vec3(-10.,2.*tan(t/(101.0-progressb)),5.0*sin(t/(101.0-progressc)))); }
                else if(typeX==3) { invertxy? dir =-normalize(vec3(-10.,2.*sin(t/(101.0-progressc)),5.0*ceil(t/(101.0-progressb)))) : dir =-normalize(vec3(-10.,2.*ceil(t/(101.0-progressb)),5.0*sin(t/(101.0-progressc)))); uv /= 0.05; }
                // dir=-normalize(vec3(-10.,2.*sin(t/10.),-4.*sin(t/10.))),
                vec3 up = vec3(0.,0.,1.);
                vec3 k=vec3(1,2,3)/3.;
                vec3 col=k-k;

            up=normalize(up-dir*dot(dir,up));

            dir=normalize(dir+=cross(dir,up)*uv.x+s.y/s.x*up*uv.y);        

            for (float a =0.;a<3.14159; a += 1.152)
            {
                df += 0.05;

                dir *= mat3(1.,1.,1.,0.,cos(a),-sin(a),0.,sin(a),cos(a));

                vec2 p = dir.zx / max(.001, abs(dir.y))*vec2(3., 0.18);

                p.y += t * 12. + a ;

                sgn = sign(dir.y);
                h = hash(floor((p+=.5+a)*sgn));
                h2 = hash(floor(p.y/6.));
                h3 = hash(floor(p.y/20.*a)+sgn);
                band = abs(p.x) < 2. + floor(30.*h3*h3) ? 1. : 0.;
                ff = h2 < .5 ? smoothstep(.6, 0.,length( mod(p, vec2(1.)) - .5))*6. : 2.;

                h = h < h2/1.2 + .1 ? 1. : 0.;

                col += .9 * mix(k, clamp(abs(fract(h2/5.+t/30.+k)*6. - 3.) - k, 0., 1.), .9) * h * band * 3. * ff * pow(abs(dir.y),0.5);  
            }
            fragColor.rgb = clamp(col*.25, 0., 1.)+df;
            fragColor.a = 1.0;

            // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // vec4 gradmap;
            // float luminance = dot(fragColor.rgb, luminanceWeighting);
            // gradmap = mix(color1,color2,luminance)*fragColor.a;

    	// vec4 factorx = mix(fragColor,gradmap,alphab);
    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
